  let feedback=document.getElementById('evFeedback')?.value||'';
  let body={id:st.evaluationEditId||null,player_id:pid,sport:sport,evaluation_date:new Date().toISOString().slice(0,10),overall_rating:overall,level:level,scores:scores,strengths:'',focus_areas:'',comments:feedback};
